697					if err := snd.WriteFrame(ReliableFrame{Kind: uint8(i), Payload: []byte(fmt.Sprintf("payload-%d", i))}); err != nil {
698						t.Fatal(err)
699					}
700				}
701				snd.Close()
702	
703				path := filepath.Join(dir, logName)
704				data, err := os.ReadFile(path)
705				if err != nil {
706					t.Fatal(err)
707				}
708				switch damage {
709				case "truncate":
710					data = data[:len(data)-3] // cut through the final record
711				case "bitflip":
712					data[logHdrSize+2] ^= 0x01 // flip one payload byte of record 0
713				}
714				if err := os.WriteFile(path, data, 0o644); err != nil {
715					t.Fatal(err)
716				}
717	
718				// Recovery refuses to start: the established checksum value,
719				// so no frame is replayed from damaged state.
720				var buf bytes.Buffer
721				_, err = NewReliable(NewSession(&buf, closedReader{}), ReliableConfig{Window: 8, StateDir: dir})
722				if !errors.Is(err, ErrChecksum) {
723					t.Fatalf("damaged log (%s) err = %v, want ErrChecksum", damage, err)
724				}
725			})
726		}
727	}
