1008	func TestReliableFullDuplexOrdered(t *testing.T) {
1009		a, b := net.Pipe()
1010		sa, err := NewReliable(NewSession(a, a), ReliableConfig{Window: 128, StateDir: t.TempDir()})
1011		if err != nil {
1012			t.Fatal(err)
1013		}
1014		sb, err := NewReliable(NewSession(b, b), ReliableConfig{Window: 128, StateDir: t.TempDir()})
1015		if err != nil {
1016			t.Fatal(err)
1017		}
1018	
1019		const n = 60
1020		got := make([]ReliableFrame, 0, n)
1021		var gotMu sync.Mutex
1022		receivedAll := make(chan struct{})
1023	
1024		// A has no inbound data; its reader only consumes B's acks so the
1025		// pipe and B's ack pump never block.
1026		go func() {
1027			for {
1028				if _, err := sa.ReadFrame(); err != nil {
1029					return
1030				}
1031			}
1032		}()
1033	
1034		// B receives every data frame exactly once, in write order.
1035		go func() {
1036			for {
1037				f, err := sb.ReadFrame()
1038				if err != nil {
1039					return
1040				}
1041				gotMu.Lock()
1042				got = append(got, f)
1043				done := len(got) == n
1044				gotMu.Unlock()
1045				if done {
1046					close(receivedAll)
1047					return
1048				}
1049			}
1050		}()
1051	
1052		// Write in batches with flushes in between, like a pipelined caller.
1053		for i := 0; i < n; i++ {
1054			if err := sa.WriteFrame(ReliableFrame{
1055				Flags: uint16(i), Kind: uint8(i % 250), Payload: []byte(fmt.Sprintf("p%04d", i)),
1056			}); err != nil {
1057				t.Fatalf("write %d: %v", i, err)
1058			}
1059			if i%7 == 0 {
1060				if err := sa.Flush(); err != nil {
1061					t.Fatalf("flush %d: %v", i, err)
1062				}
1063			}
1064		}
1065		if err := sa.Flush(); err != nil {
1066			t.Fatalf("final flush: %v", err)
1067		}
1068	
1069		<-receivedAll
1070		a.Close()
1071		b.Close()
1072		sa.Close()
1073		sb.Close()
1074	
1075		gotMu.Lock()
1076		defer gotMu.Unlock()
1077		if len(got) != n {
1078			t.Fatalf("got %d frames, want %d", len(got), n)
1079		}
1080		for i := range got {
1081			want := fmt.Sprintf("p%04d", i)
1082			if string(got[i].Payload) != want {
1083				t.Fatalf("frame %d = %q, want %q: ordering changed or a duplicate", i, got[i].Payload, want)
1084			}
1085		}
1086	}
