// ---- full duplex over a real byte stream ------------------------------------

func newMuxPair(t *testing.T, channels, window, relWindow int) (a, b *Mux) {
	t.Helper()
	pa, pb := net.Pipe()
	rsa, err := NewReliable(NewSession(pa, pa), ReliableConfig{Window: relWindow, StateDir: t.TempDir()})
	if err != nil {
		t.Fatal(err)
	}
	rsb, err := NewReliable(NewSession(pb, pb), ReliableConfig{Window: relWindow, StateDir: t.TempDir()})
	if err != nil {
