func newMuxPair(t *testing.T, channels, window, relWindow int) (a, b *Mux) {
	t.Helper()
	pa, pb := net.Pipe()
	rsa, err := NewReliable(NewSession(pa, pa), ReliableConfig{Window: relWindow, StateDir: t.TempDir()})
	if err != nil {
		t.Fatal(err)
	}
	rsb, err := NewReliable(NewSession(pb, pb), ReliableConfig{Window: relWindow, StateDir: t.TempDir()})
	if err != nil {
		t.Fatal(err)
	}
	a, err = NewMux(rsa, MuxConfig{Channels: channels, Window: window, StateDir: t.TempDir()})
	if err != nil {
		t.Fatal(err)
	}
	b, err = NewMux(rsb, MuxConfig{Channels: channels, Window: window, StateDir: t.TempDir()})
	if err != nil {
		t.Fatal(err)
	}
	t.Cleanup(func() {
		a.Close()
		b.Close()
		rsa.Close()
		rsb.Close()
		pa.Close()
		pb.Close()
	})
	return a, b
}

func writeUntilAccepted(t *testing.T, m *Mux, cf ChannelFrame) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for {
		err := m.WriteFrame(cf)
		if err == nil {
			return
		}
		if errors.Is(err, ErrWindowFull) {
			if time.Now().After(deadline) {
				t.Fatalf("WriteFrame stayed full: %v", err)
			}
			time.Sleep(time.Millisecond)
			continue
		}
		t.Fatalf("WriteFrame: %v", err)
	}
}

func closeUntilAccepted(t *testing.T, m *Mux, ch uint16) {
	t.Helper()
	deadline := time.Now().Add(5 * time.Second)
	for {
		err := m.CloseChannel(ch)
		if err == nil {
			return
		}
		if errors.Is(err, ErrWindowFull) {
			if time.Now().After(deadline) {
				t.Fatalf("CloseChannel stayed full: %v", err)
			}
			time.Sleep(time.Millisecond)
			continue
		}
		t.Fatalf("CloseChannel: %v", err)
	}
}

func TestMuxFullDuplexPerChannelExactlyOnce(t *testing.T) {
	const channels = 4
	const perChannel = 60
	a, b := newMuxPair(t, channels, 8, 256)

	// A's inbound direction carries only B's acknowledgements; drain it
	// so A's windows keep advancing.
	go func() {
		for {
			if _, err := a.ReadFrame(); err != nil {
				return
			}
		}
	}()

	type received struct {
		cf ChannelFrame
	}
	var mu sync.Mutex
	perCh := make([][]int, channels)
	eofs := make(map[uint16]int)
	allDone := make(chan struct{})

	// Single reader on B: per-channel order must match write order; each
	// channel ends with exactly one io.EOF naming it.
	go func() {
		for {
			cf, err := b.ReadFrame()
			if errors.Is(err, io.EOF) {
				mu.Lock()
				eofs[cf.Channel]++
				done := len(eofs) == channels
				mu.Unlock()
				if done {
					close(allDone)
					return
				}
				continue
			}
			if err != nil {
				return
			}
			var idx int
			if _, err := fmt.Sscanf(string(cf.Payload), "c%df%d", new(int), &idx); err != nil {
				// Parse using the channel instead; payload format is c<ch>f<idx>.
			}
			mu.Lock()
			perCh[cf.Channel] = append(perCh[cf.Channel], idx)
			mu.Unlock()
		}
	}()

	for ch := 0; ch < channels; ch++ {
		for i := 0; i < perChannel; i++ {
			writeUntilAccepted(t, a, ChannelFrame{
				Channel: uint16(ch),
				Kind:    uint8(ch),
				Payload: []byte(fmt.Sprintf("c%df%04d", ch, i)),
			})
		}
		if err := a.Flush(); err != nil {
			t.Fatalf("flush ch%d: %v", ch, err)
		}
	}
	for ch := 0; ch < channels; ch++ {
		closeUntilAccepted(t, a, uint16(ch))
	}
	if err := a.Flush(); err != nil {
		t.Fatalf("final flush: %v", err)
	}

	select {
	case <-allDone:
	case <-time.After(10 * time.Second):
		t.Fatal("timed out waiting for all frames and FINs")
	}

	mu.Lock()
	defer mu.Unlock()
	for ch := 0; ch < channels; ch++ {
		got := perCh[ch]
		if len(got) != perChannel {
			t.Fatalf("ch%d got %d frames, want %d", ch, len(got), perChannel)
		}
		for i, idx := range got {
			if idx != i {
				t.Fatalf("ch%d delivery order broken at %d: got %d, want %d", ch, i, idx, i)
			}
		}
		if eofs[uint16(ch)] != 1 {
			t.Fatalf("ch%d EOF count = %d, want 1", ch, eofs[uint16(ch)])
		}
	}
}

func TestMuxConcurrentWritersSameChannelNoLoss(t *testing.T) {
	const channels = 2
	const writers = 8
	const per = 50
	a, b := newMuxPair(t, channels, 4, 256)

	go func() {
		for {
			if _, err := a.ReadFrame(); err != nil {
				return
			}
		}
	}()

	var wg sync.WaitGroup
	for g := 0; g < writers; g++ {
		wg.Add(1)
		go func(g int) {
			defer wg.Done()
			for i := 0; i < per; i++ {
				writeUntilAccepted(t, a, ChannelFrame{
					Channel: uint16(g % channels),
					Kind:    uint8(g),
					Payload: []byte(fmt.Sprintf("g%02di%04d", g, i)),
				})
			}
		}(g)
	}

	expected := writers * per
	counts := make(map[string]int)
	var cmu sync.Mutex
	readerDone := make(chan struct{})
	go func() {
		for {
			cf, err := b.ReadFrame()
			if err != nil {
				return
			}
			cmu.Lock()
			counts[string(cf.Payload)]++
			n := len(counts)
			cmu.Unlock()
			if n == expected {
				close(readerDone)
				return
			}
		}
	}()

	wg.Wait()
	if err := a.Flush(); err != nil {
		t.Fatal(err)
	}
	select {
	case <-readerDone:
	case <-time.After(10 * time.Second):
		t.Fatal("timed out; frames lost or interleaved")
	}

	cmu.Lock()
	defer cmu.Unlock()
	if len(counts) != expected {
		t.Fatalf("distinct frames = %d, want %d", len(counts), expected)
	}
	keys := make([]string, 0, expected)
	for k := range counts {
		keys = append(keys, k)
		if counts[k] != 1 {
			t.Fatalf("frame %q delivered %d times", k, counts[k])
		}
	}
	sort.Strings(keys)
	_ = keys
}

