// flushLoop periodically flushes m so acknowledgements and data keep
// moving over a blocking full-duplex pipe.
func flushLoop(t *testing.T, m *Mux) chan struct{} {
	t.Helper()
	stop := make(chan struct{})
	go func() {
		for {
			select {
			case <-stop:
				return
			default:
				_ = m.Flush()
				time.Sleep(2 * time.Millisecond)
			}
		}
	}()
	return stop
}

