// confirmed position, rewriting the journal atomically via temp file
// plus rename.
func (l *muxLog) prefix(sc []sendChannel) error {
	l.mu.Lock()
	defer l.mu.Unlock()

	keep := l.recs[:0]
	for _, r := range l.recs {
		if int(r.ch) < len(sc) && r.seq < sc[r.ch].acked {
			continue
		}
		keep = append(keep, r)
	}

