	const writers = 8
	const per = 50
	a, b := newMuxPair(t, channels, 4, 256)

	stopFlush := flushLoop(t, a)
	defer close(stopFlush)

	go func() {
		for {
			if _, err := a.ReadFrame(); err != nil {
				return
			}
		}
	}()

	var wg sync.WaitGroup
	errCh := make(chan error, writers)
	for g := 0; g < writers; g++ {
		wg.Add(1)
		go func(g int) {
			defer wg.Done()
			for i := 0; i < per; i++ {
				if err := writeAccepted(a, ChannelFrame{
					Channel: uint16(g % channels),
					Kind:    uint8(g),
					Payload: []byte(fmt.Sprintf("g%02di%04d", g, i)),
				}); err != nil {
					errCh <- err
					return
				}
			}
		}(g)
	}

	expected := writers * per
	counts := make(map[string]int)
	var cmu sync.Mutex
	readerDone := make(chan struct{})
	go func() {
		for {
			cf, err := b.ReadFrame()
			if err != nil {
				return
			}
			cmu.Lock()
			counts[string(cf.Payload)]++
			n := len(counts)
			cmu.Unlock()
			if n == expected {
				close(readerDone)
				return
			}
		}
	}()

	wg.Wait()
	select {
	case err := <-errCh:
		t.Fatalf("writer: %v", err)
	default:
	}
	if err := a.Flush(); err != nil {
		t.Fatal(err)
	}
	select {
	case <-readerDone:
	case <-time.After(10 * time.Second):
		t.Fatal("timed out; frames lost or interleaved")
	}
	select {
	case err := <-errCh:
		t.Fatalf("writer: %v", err)
	default:
	}

	cmu.Lock()
	defer cmu.Unlock()
	if len(counts) != expected {
		t.Fatalf("distinct frames = %d, want %d", len(counts), expected)
	}
	keys := make([]string, 0, expected)
	for k := range counts {
		keys = append(keys, k)
		if counts[k] != 1 {
			t.Fatalf("frame %q delivered %d times", k, counts[k])
		}
	}
	sort.Strings(keys)
	_ = keys
}

